/**
 * Site-connection flow.
 *
 * Possessing a Bludit URL and an API token is *not* proof of ownership and is
 * not treated as proof. Connecting a site requires three independent things:
 *
 *  1. **A signed-in account on this service.** Proves a real user is acting.
 *  2. **A single-use pairing challenge**, generated by that account and shown
 *     once. It is short-lived, bound to the account, and stored only as a keyed
 *     hash, so a database leak does not disclose outstanding challenges.
 *  3. **Site-side proof of control.** The target site must echo the challenge,
 *     either through the Wizard extension's HMAC proof or through a
 *     `/.well-known/` file. This is what stops one tenant from claiming another
 *     tenant's Bludit site by pasting its URL.
 *
 * The challenge is never stored in plaintext and never reused.
 */

import { ToolError } from '../shared/errors.js';
import { constantTimeEqual, hmacBase64Url, hmacHex, randomToken } from '../shared/crypto.js';
import { DEFAULT_PAIRING_TTL_SECONDS, intVar, type SharedSecrets } from '../shared/env.js';

export interface PairingChallengeRow {
  id: string;
  user_id: string;
  label: string;
  base_url: string;
  created_at: number;
  expires_at: number;
  consumed_at: number | null;
}

export interface CreatedChallenge {
  /** The keyed hash, usable as the challenge's public handle. */
  id: string;
  /** The secret to show the user exactly once. Never persisted or logged. */
  challenge: string;
  expiresAt: number;
}

export function pairingTtlSeconds(env: SharedSecrets): number {
  return intVar(env.PAIRING_TTL_SECONDS, DEFAULT_PAIRING_TTL_SECONDS);
}

export async function createPairingChallenge(
  db: D1Database,
  sessionSecret: string,
  userId: string,
  input: { label?: string; baseUrl?: string; ttlSeconds?: number; now?: number }
): Promise<CreatedChallenge> {
  const now = input.now ?? Date.now();
  const challenge = randomToken(32);
  const id = await hmacHex(sessionSecret, challenge);
  const ttl = (input.ttlSeconds ?? DEFAULT_PAIRING_TTL_SECONDS) * 1000;
  const expiresAt = now + ttl;

  await db
    .prepare(
      `INSERT INTO pairing_challenges (id, user_id, challenge_hash, label, base_url, created_at, expires_at, consumed_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, NULL)`
    )
    .bind(id, userId, id, (input.label ?? '').slice(0, 120), input.baseUrl ?? '', now, expiresAt)
    .run();

  return { id, challenge, expiresAt };
}

export async function findChallenge(
  db: D1Database,
  sessionSecret: string,
  userId: string,
  challenge: string
): Promise<PairingChallengeRow> {
  if (challenge.trim() === '') {
    throw new ToolError('invalid_input', 'A pairing challenge is required.');
  }
  const id = await hmacHex(sessionSecret, challenge.trim());
  const row = await db
    .prepare('SELECT * FROM pairing_challenges WHERE id = ? AND user_id = ?')
    .bind(id, userId)
    .first<PairingChallengeRow>();

  if (!row) {
    throw new ToolError('not_found', 'That pairing challenge is not recognised for this account.');
  }
  if (row.consumed_at !== null) {
    throw new ToolError('conflict', 'That pairing challenge has already been used.');
  }
  if (row.expires_at <= Date.now()) {
    throw new ToolError('proposal_expired', 'That pairing challenge has expired. Generate a new one.');
  }
  return row;
}

/** Mark a challenge used. Single-use is enforced in the UPDATE's WHERE clause. */
export async function consumeChallenge(
  db: D1Database,
  userId: string,
  challengeId: string,
  now = Date.now()
): Promise<boolean> {
  const result = await db
    .prepare('UPDATE pairing_challenges SET consumed_at = ? WHERE id = ? AND user_id = ? AND consumed_at IS NULL')
    .bind(now, challengeId, userId)
    .run();
  return (result.meta?.changes ?? 0) > 0;
}

export async function purgeExpiredChallenges(db: D1Database, now = Date.now()): Promise<number> {
  const result = await db.prepare('DELETE FROM pairing_challenges WHERE expires_at < ?').bind(now).run();
  return result.meta?.changes ?? 0;
}

/**
 * Verify the Wizard extension's pairing proof.
 *
 * Contract: `proof = base64url(HMAC-SHA256(key = GPT Action API key, message = challenge))`.
 * The comparison is constant-time.
 */
export async function verifyWizardProof(
  wizardApiKey: string,
  challenge: string,
  proof: string
): Promise<boolean> {
  if (wizardApiKey === '' || proof === '') return false;
  const expected = await hmacBase64Url(wizardApiKey, challenge);
  return constantTimeEqual(expected, proof.trim());
}

/** Constant-time comparison of a `/.well-known/` file body against the challenge. */
export function verifyWellKnownBody(challenge: string, body: string): boolean {
  return constantTimeEqual(challenge, body.trim());
}

/** Path of the fallback ownership file. */
export const WELL_KNOWN_CHALLENGE_PATH = '/.well-known/bludit-wizard-challenge.txt';
